220	     * The owner's numeric membership level, assigned at creation. Starts at {@code 1}, plus 1 when
221	     * an email is present, plus 1 when {@link #namesakeCount} is 0, capped at {@code 3} (level 4 is
222	     * reserved for tenure).
223	     */
224	    public Integer getMembershipLevel() {
225	        int level = 1;
226	        if (this.email != null && !this.email.isEmpty()) {
227	            level++;
228	        }
229	        if (this.namesakeCount != null && this.namesakeCount == 0) {
230	            level++;
231	        }
232	        return Math.min(level, 3);
233	    }
