235	    /** Fixed city-to-region table used to derive {@link #getLocality()}. */
236	    private static final Map<String, String> CITY_REGION = Map.of(
237	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
238	
239	    /** Region -> inclusive 4-digit postcode range {low, high} used to derive {@link #getLocality()}. */
240	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
241	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
242	
243	    /**
244	     * The fixed city-to-region mapping ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
245	     * {@code Brisbane -> QLD}): the region for {@code city}, or {@code null} when the city is not in
246	     * the table. Used only by postcode validation, which branches on "known region or not" by testing
247	     * for {@code null} before range-checking the postcode.
248	     */
