254	     * The region whose fixed postcode range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
255	     * {@code QLD 4000-4099}) contains {@code postcode}, or {@code null} when {@code postcode} is
256	     * absent, not a 4-digit number, or in no known range.
257	     */
258	    public static String regionOfPostcode(String postcode) {
259	        if (postcode == null || postcode.isEmpty()) {
260	            return null;
261	        }
262	        int value;
263	        try {
264	            value = Integer.parseInt(postcode);
265	        } catch (NumberFormatException ex) {
266	            return null;
267	        }
268	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
269	            int[] range = entry.getValue();
270	            if (value >= range[0] && value <= range[1]) {
271	                return entry.getKey();
272	            }
273	        }
274	        return null;
275	    }
