300	    /**
301	     * A single Luhn check digit (0-9) derived at response time over the digits contained in
302	     * {@link #customerCode} (non-digit characters are ignored), or {@code null} when the owner
303	     * has no customer code. Computed with the standard Luhn algorithm — doubling every second
304	     * digit from the right, subtracting 9 from any result over 9, and taking
305	     * {@code (10 - sum % 10) % 10}. Not persisted.
306	     */
307	    public Integer getCheckDigit() {
308	        if (this.customerCode == null) {
309	            return null;
310	        }
311	        int sum = 0;
312	        boolean dbl = true;
313	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
314	            char c = this.customerCode.charAt(i);
315	            if (c < '0' || c > '9') {
316	                continue;
317	            }
318	            int d = c - '0';
319	            if (dbl) {
320	                d *= 2;
321	                if (d > 9) {
322	                    d -= 9;
323	                }
324	            }
325	            sum += d;
326	            dbl = !dbl;
327	        }
328	        return (10 - (sum % 10)) % 10;
329	    }
