331	    /**
332	     * The single source of truth for an owner's identity: the derived key
333	     * {@code normalizedTelephone|email|householdId}, joined with '|'. The telephone is stored in
334	     * canonical E.164 form and the email lower-cased, so this key composes their canonical values;
335	     * an absent email or householdId contributes an empty segment. Two owners are duplicates exactly
336	     * when their whole identity keys are equal — differing in any one segment (for example two
337	     * members of the same household with different telephones) yields different keys. Derived at
338	     * response time and used by the create pipeline's single duplicate check; not persisted.
339	     */
340	    public String getIdentityKey() {
341	        return keyPart(this.telephone) + "|" + keyPart(this.email) + "|" + keyPart(this.householdId);
342	    }
