359	    public List<Pet> getPets() {
360	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
361	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
362	        return Collections.unmodifiableList(sortedPets);
363	    }
364	
365	    public void setPets(List<Pet> pets) {
366	        this.pets = new HashSet<>(pets);
367	    }
368	
369	    public void addPet(Pet pet) {
370	        getPetsInternal().add(pet);
371	        pet.setOwner(this);
372	    }
