374	    /**
375	     * Return the Pet with the given name, or null if none found for this Owner.
376	     *
377	     * @param name to test
378	     * @return true if pet name is already in use
379	     */
380	    public Pet getPet(String name) {
381	        return getPet(name, false);
382	    }
383	
384	    /**
385	     * Return the Pet with the given name, or null if none found for this Owner.
386	     *
387	     * @param name to test
388	     * @return true if pet name is already in use
389	     */
390	    public Pet getPet(String name, boolean ignoreNew) {
391	        name = name.toLowerCase();
392	        for (Pet pet : getPetsInternal()) {
393	            if (!ignoreNew || !pet.isNew()) {
394	                String compName = pet.getName();
395	                compName = compName.toLowerCase();
396	                if (compName.equals(name)) {
397	                    return pet;
398	                }
399	            }
400	        }
401	        return null;
402	    }
403	
404	    public Pet getPet(Integer petId) {
405	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
406	    }
407	
408	    @Override
409	    public String toString() {
410	        return new ToStringCreator(this)
411	
412	            .append("id", this.getId())
413	            .append("new", this.isNew())
414	            .append("lastName", this.getLastName())
415	            .append("firstName", this.getFirstName())
416	            .append("address", this.address)
417	            .append("city", this.city)
418	            .append("telephone", this.telephone)
419	            .append("email", this.email)
420	            .toString();
421	    }
422	}
